            compartments[pi] += 1
            for i in range(pi + 1, K + 1):
                if compartments[i] > 0:
                    break
            else:
                for i in range(pi - 1, 0, -1):
                    if compartments[i] > 0:
                        break
            for i in range(pi - 1, i - 1, -1):
                if compartments[i] == 0:
                    compartments[i] += 1
                    break
        print(sum(1 for x in compartments if x > 0))

