    N, Q = map(int, input().split())
    v = list(map(int, input().split()))
    queries = []
    for _ in range(Q):
        x, y = map(int, input().split())
        queries.append((x, y))
    for x, y in queries:
        dp = [[float('inf')] * N for _ in range(N)]
        dp[x-1][x-1] = 0
        pq = [(0, x-1)]
        heapify(pq)
        while pq:
            c, i = heappop(pq)
            if c > dp[i][y-1]:
                break
            for j in range(N):
                if v[j] != v[i]:
                    d = abs(v[j] - v[i]) + j - i
                    if c + d < dp[j][y-1]:
                        dp[j][y-1] = c + d
                        heappush(pq, (c + d, j))
        if dp[x-1][y-1] == float('inf'):
            print(-1, -1)
        else:
            min_cost = dp[x-1][y-1]
            max_len = 0
            for i in range(x-1, y):
                if dp[i][y-1] == min_cost:
                    max_len = max(max_len, i - x + 2)
            print(min_cost, max_len)

