class Node:
    def __init__(self, num):
        self.num = num
        self.parent = None
        self.children = []

def find(x, target):
    if x.parent is None:
        return x.num
    if x.parent.num == target:
        return x.num
    return find(x.parent, target)

for _ in range(int(input())):
    n, q = map(int, input().split())
    nodes = [Node(i) for i in range(1, n+1)]
    for _ in range(n-1):
        u, v = map(int, input().split())
        nodes[u-1].children.append(nodes[v-1])
        nodes[v-1].parent = nodes[u-1]
    for _ in range(q):
        a, da, b, db = map(int, input().split())
        a = find(nodes[a-1], a)
        b = find(nodes[b-1], b)
        if a == b:
            print(-1)
        elif da == db:
            print(a)
        else:
            print(b)

