def solve():
    N, NSP, Q = map(int, input().split())
    edges = list(map(int, input().split()))
    costs = list(map(int, input().split()))
    special_nodes = list(map(int, input().split()))
    queries = []
    for _ in range(Q):
        SNODE, DNODE, W = map(int, input().split())
        queries.append((SNODE, DNODE, W))
    graph = [[] for _ in range(N)]
    for i in range(N-1):
        graph[edges[i]].append(i+1)
        graph[i+1].append(edges[i])
    memo = {}
    def dfs(node, parent, cost, W):
        if (node, W) in memo:
            return memo[(node, W)]
        if node == DNODE:
            return 0
        res = float('inf')
        for next_node in graph[node]:
            if next_node != parent:
                next_cost = cost + costs[next_node]
                if next_cost <= W:
                    res = min(res, abs(next_cost - next_cost + dfs(next_node, node, next_cost, W)))
        memo[(node, W)] = res
        return res
    for SNODE, DNODE, W in queries:
        res = dfs(SNODE, -1, 0, W)
        print(res)

