def solve():
    T = int(input())
    for _ in range(T):
        N, M, K = map(int, input().split())
        roads = [[] for _ in range(N + 1)]
        for _ in range(M):
            u, v = map(int, input().split())
            roads[u].append(v)
            roads[v].append(u)
        Q = int(input())
        conditions = [(0, 0)]
        for _ in range(Q):
            a, b = map(int, input().split())
            conditions.append((a, b))
        conditions.sort()
        dp = [[0] * (K + 1) for _ in range(N + 1)]
        dp[1][0] = 1
        for a, b in conditions:
            for j in range(K, b - 1, -1):
                dp[a][j] = (dp[a][j] + dp[a][j - 1]) % MOD
        for j in range(1, K + 1):
            for i in range(1, N + 1):
                for v in roads[i]:
                    if j > 1:
                        dp[i][j] = (dp[i][j] + dp[v][j - 1]) % MOD
                    else:
                        dp[i][j] = dp[v][j]
        print(dp[N][K])

