def query():
    n = int(input())
    tree = {}
    for _ in range(n-1):
        x, y = map(int, input().split())
        if x not in tree:
            tree[x] = []
        if y not in tree:
            tree[y] = []
        tree[x].append(y)
        tree[y].append(x)
    visited = set()
    max_size = 0
    for node in tree:
        if node not in visited:
            size = 0
            queue = deque([node])
            visited.add(node)
            while queue:
                size += 1
                node = queue.popleft()
                for neighbor in tree[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            max_size = max(max_size, size)
    print(max_size)

