from collections import deque

def solve():
    T = int(input())
    for _ in range(T):
        N = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        if sum(a) != sum(b):
            print("No")
        else:
            queue = deque([(0, 0, 0)])
            visited = set((0, 0))
            while queue:
                v, a_sum, b_sum = queue.popleft()
                if v == N:
                    if a_sum == a[-1] and b_sum == b[-1]:
                        print("Yes")
                        return
                for i in range(1, v):
                    if (v - i, a_sum + a[i - 1], b_sum + b[i - 1]) not in visited:
                        queue.append((v - i, a_sum + a[i - 1], b_sum + b[i - 1]))
                        visited.add((v - i, a_sum + a[i - 1], b_sum + b[i - 1]))
                for i in range(v + 1, N + 1):
                    if (i - v, a_sum + a[v - 1], b_sum + b[v - 1]) not in visited:
                        queue.append((i - v, a_sum + a[v - 1], b_sum + b[v - 1]))
                        visited.add((i - v, a_sum + a[v - 1], b_sum + b[v - 1]))
            print("No")

