    strawberry, blueberry = 0, 0
    for jar in jars[:n]:
        if jar == 1:
            strawberry += 1
        else:
            blueberry += 1
    for jar in jars[n:]:
        if jar == 1:
            blueberry += 1
        else:
            strawberry += 1
    return abs(strawberry - blueberry)

