def largest_nice_number(n):
    s = list(str(n))
    i = len(s) - 2
    while i >= 0 and s[i] >= s[i + 1]:
        i -= 1
    if i == -1:
        return -1
    j = len(s) - 1
    while s[j] <= s[i]:
        j -= 1
    s[i], s[j] = s[j], s[i]
    s = s[:i + 1] + sorted(s[i + 1:])
    return int(''.join(s))

