def can_form_sequence(words):
    n = len(words)
    for i in range(n):
        for j in range(n):
            if i != j and words[i][-1] == words[j][0]:
                return True
    return False

def find_min_reversals(words):
    n = len(words)
    if can_form_sequence(words):
        return 0, []
    for i in range(n):
        reversed_word = words[i][::-1]
        if can_form_sequence([reversed_word] + words[:i] + words[i+1:]):
            return 1, [i+1]
    return -1, []

