def solve(n, p, c):
    graph = [[] for _ in range(n+1)]
    for i in range(n):
        graph[p[i]].append(i+1)

    colors = [0] * (n+1)
    for i in range(n):
        colors[i+1] = c[i]

    def dfs(node, color):
        if colors[node] != color:
            return False
        if node in visited:
            return node
        visited.add(node)
        for neighbor in graph[node]:
            if not dfs(neighbor, color):
                return False
        return False

    for i in range(1, n+1):
        if colors[i] == 0:
            visited = set()
            start = dfs(i, colors[i])
            if start:
                cycle = []
                while start:
                    cycle.append(start)
                    start = dfs(start, colors[i])
                cycle_length = len(cycle)
                return cycle_length

    return 1

