def max_score(N, board, points):
    max_score = 0
    for i in range(N - 7):
        score = 0
        double_word = False
        triple_word = False
        for j in range(8):
            if board[i + j] == 'd':
                score += 2 * points[j]
            elif board[i + j] == 't':
                score += 3 * points[j]
            elif board[i + j] == 'D':
                double_word = True
            elif board[i + j] == 'T':
                triple_word = True
            else:
                score += points[j]
        if double_word:
            score *= 2
        if triple_word:
            score *= 3
        max_score = max(max_score, score)
    return max_score

