def count_valid_shifts(N, W):
    max_sweetness = max(W)
    prefix_max = [W[0]]
    for i in range(1, N):
        prefix_max.append(max(prefix_max[-1], W[i]))

    suffix_max = [W[-1]]
    for i in range(N-2, -1, -1):
        suffix_max.append(max(suffix_max[-1], W[i]))
    suffix_max.reverse()

    valid_shifts = 0
    for k in range(N):
        if prefix_max[k] < max_sweetness and suffix_max[k] < max_sweetness:
            valid_shifts += 1
    return valid_shifts

