def is_valid_cobra_strip(heights):
    n = len(heights)
    if heights[0] != 1 or heights[-1] != 1:
        return "no"
    center = n // 2
    if n % 2 == 0:
        return "no"
    for i in range(1, center + 1):
        if heights[i] != heights[i - 1] + 1:
            return "no"
    for i in range(center, n - 1):
        if heights[i] != heights[i + 1] - 1:
            return "no"
    return "yes"

