def min_hits(S, W1, W2, W3):
    stack = [W1, W2, W3]
    hits = 0
    while stack:
        if stack[-1] <= S:
            stack.pop()
        else:
            k = 0
            while k < len(stack) and sum(stack[k:]) <= S:
                k += 1
            stack = stack[k:]
            hits += 1
    return hits

