import sys
from collections import defaultdict

def simulate_ants(R, C, grid):
    ants = defaultdict(list)
    for i in range(R):
        for j in range(C):
            if grid[i][j] in 'UDLR':
                ants[(i, j)].append(grid[i][j])

    def get_next_position(pos, direction):
        x, y = pos
        if direction == 'U':
            return (x - 1, y)
        elif direction == 'D':
            return (x + 1, y)
        elif direction == 'L':
            return (x, y - 1)
        elif direction == 'R':
            return (x, y + 1)

    def is_valid(pos):
        x, y = pos
        return 0 <= x < R and 0 <= y < C

    meetings = 0
    steps = 0
    while True:
        next_positions = defaultdict(list)
        for pos, directions in ants.items():
            for direction in directions:
                next_pos = get_next_position(pos, direction)
                if is_valid(next_pos):
                    next_positions[next_pos].append(direction)

        for pos, directions in next_positions.items():
            if len(directions) > 1:
                meetings += len(directions) * (len(directions) - 1) // 2

        new_ants = defaultdict(list)
        for pos, directions in next_positions.items():
            if len(directions) == 1:
                new_ants[pos].append(directions[0])

        if not new_ants:
            break

        ants = new_ants
        steps += 1

    return meetings

