def can_sort_with_swaps(N, M, P, swaps):
    for i in range(1, N + 1):
        if P[i - 1] != i:
            found = False
            for l, r in swaps:
                if l <= i <= r:
                    if P[l - 1] == i:
                        P[l - 1], P[i - 1] = P[i - 1], P[l - 1]
                        found = True
                        break
                    if P[r - 1] == i:
                        P[r - 1], P[i - 1] = P[i - 1], P[r - 1]
                        found = True
                        break
            if not found:
                return "Impossible"
    return "Possible"

