def min_grid_area(s):
    x, y = 0, 0
    min_x, max_x, min_y, max_y = 0, 0, 0, 0
    for c in s:
        if c == 'W':
            y -= 1
        elif c == 'S':
            y += 1
        elif c == 'A':
            x -= 1
        elif c == 'D':
            x += 1
        min_x = min(min_x, x)
        max_x = max(max_x, x)
        min_y = min(min_y, y)
        max_y = max(max_y, y)
    return (max_x - min_x + 1) * (max_y - min_y + 1)

