def calculate_fence_length(N, M, plants):
    if not plants:
        return 0
    # Sort plants by their positions to facilitate grouping
    plants.sort()
    # Group plants by their row
    row_groups = {}
    for r, c in plants:
        if r not in row_groups:
            row_groups[r] = []
        row_groups[r].append(c)
    # Calculate the length of fences for each row group
    row_fences = 0
    for row, cols in row_groups.items():
        if len(cols) == 1:
            row_fences += 2  # Fences for the left and right sides of the plant
        else:
            row_fences += 2 * (len(cols) - 1)  # Fences between plants in the same row
    # Calculate the length of fences for each column group
    col_fences = 0
    for col in range(1, M + 1):
        count = 0
        for r, c in plants:
            if c == col:
                count += 1
        if count == 1:
            col_fences += 2  # Fences for the top and bottom sides of the plant
        else:
            col_fences += 2 * (count - 1)  # Fences between plants in the same column
    # Add the boundary fences
    row_fences += 2 * (N - 1)  # Horizontal boundary fences
    col_fences += 2 * (M - 1)  # Vertical boundary fences
    return row_fences + col_fences

