import sys

def can_eat_all_bananas(piles, h, k):
    hours_needed = 0
    for pile in piles:
        if pile % k == 0:
            hours_needed += pile // k
        else:
            hours_needed += pile // k + 1
    return hours_needed <= h

def min_eating_speed(piles, h):
    left, right = 1, max(piles)
    while left < right:
        mid = (left + right) // 2
        if can_eat_all_bananas(piles, h, mid):
            right = mid
        else:
            left = mid + 1
    return left

