import sys

def calculate_weight(s):
    stack = []
    num = 0
    weight = {'x': 2, 'y': 4, 'z': 10}
    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char == '(':
            stack.append(num)
            num = 0
        elif char == ')':
            prev = stack.pop()
            num = prev * num
        elif char in weight:
            num *= weight[char]
    return num

