def max_score(matrix):
    rows, cols = len(matrix), len(matrix[0])
    for i in range(rows):
        if matrix[i][0] == 0:
            for j in range(cols):
                matrix[i][j] = 1 - matrix[i][j]
    for j in range(1, cols):
        count = sum(matrix[i][j] for i in range(rows))
        if count < rows - count:
            for i in range(rows):
                matrix[i][j] = 1 - matrix[i][j]
    return sum(int(''.join(map(str, row)), 2) for row in matrix)

