def largest_correct_subboard(N, M, board, Q, c):
    def is_correct_subboard(i, j, k):
        for x in range(i, i + k):
            for y in range(j, j + k):
                if x > 0 and board[x][y] == board[x-1][y] and board[x][y] == board[x][y-1]:
                    return False
        return True

    def binary_search(i, j):
        left, right = 0, min(N - i, M - j)
        while left < right:
            mid = (left + right + 1) // 2
            if is_correct_subboard(i, j, mid):
                left = mid
            else:
                right = mid - 1
        return left

    result = []
    for ci in c:
        max_size = 0
        for i in range(N):
            for j in range(M):
                if ci >= i + j:
                    size = binary_search(i, j)
                    if size > max_size:
                        max_size = size
        result.append(max_size)
    return result

