def fill_faded_chars(s):
    n = len(s)
    left, right = 0, n - 1
    while left < right:
        if s[left] == '.':
            s[left] = s[right]
        elif s[right] == '.':
            s[right] = s[left]
        left += 1
        right -= 1
    return ''.join(s)

