def prime_factors_sum(n):
    if n == 1:
        return 0
    sum_factors = 0
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            sum_factors += i
            if i != n // i:
                sum_factors += n // i
    if n > 1:
        sum_factors += n
    return sum_factors

