    pairs = 0
    for i in range(n):
        for j in range(n):
            if i != j and a[i] != 0 and a[j] % a[i] == 0:
                if prime_factors_sum(a[i]) != 0 and prime_factors_sum(a[j]) % prime_factors_sum(a[i]) == 0:
                    pairs += 1
    return pairs

