def can_flow(n, top_row, bottom_row):
    directions = {
        1: [0, 1], 2: [0, -1], 3: [-1, 0], 4: [1, 0], 5: [-1, 0], 6: [1, 0]
    }
    stack = [(0, 0, 1, 0)]
    visited = set()

    while stack:
        x, y, dx, dy = stack.pop()
        if (x, y, dx, dy) in visited:
            continue
        visited.add((x, y, dx, dy))

        if x == n and y == 0:
            return True

        for i in range(1, 7):
            nx, ny = x + directions[i][0], y + directions[i][1]
            if 0 <= nx < n and 0 <= ny < 2 and (nx, ny) not in visited:
                stack.append((nx, ny, directions[i][0], directions[i][1]))

    return False

