    for _ in range(T):
        M, N = map(int, input().split())
        C = [list(input().strip()) for _ in range(M)]
        dp = [[float('inf')] * N for _ in range(M)]

        # Initialize the first row
        for j in range(N):
            if C[0][j] == 'P':
                dp[0][j] = 0

        # Fill the dp table
        for i in range(1, M):
            for j in range(N):
                if C[i][j] == 'P':
                    # Calculate minimum time to reach this spot from any spot on the previous level
                    dp[i][j] = min(dp[i-1][j-1] if j > 0 else float('inf'), dp[i-1][j] if j < N-1 else float('inf')) + 1

        # The result is the minimum value in the last row
        print(min(dp[-1]))

