def solve(n):
    res = [0] * n
    p = n
    stack = []
    for i in range(n - 1, -1, -1):
        if not stack:
            stack.append(i)
            p = i
        else:
            if stack[-1] - stack[0] + 1 > p:
                if (stack[-1] - stack[0] + 1) % 2 == 1:
                    res[stack[-1] - (stack[-1] - stack[0]) // 2] = i + 1
                else:
                    res[(stack[-1] + stack[0] - 1) // 2] = i + 1
                p = i
            else:
                stack.pop()
    return res

