def max_operations(p, q, r, a, b, c):
    if (p, q, r) == (a, b, c):
        return 0
    operations = 0
    while (p, q, r) != (a, b, c):
        max_val = max(p, q, r)
        min_val = min(p, q, r)
        if max_val == a and min_val == c:
            p += (a - max_val)
            r -= (a - max_val)
        elif max_val == b and min_val == c:
            q += (b - max_val)
            r -= (b - max_val)
        elif max_val == b and min_val == a:
            p += (b - max_val)
            q -= (b - max_val)
        else:
            return -1
        operations += 1
    return operations

