import string

def solve(s, k):
    alphabet = list(string.ascii_lowercase)
    unique_chars = set(s)
    if len(unique_chars) + k >= 26:
        return "NOPE"
    else:
        target_chars = set(alphabet) - unique_chars
        result = []
        for char in s:
            if k == 0:
                result.append(next(filter(lambda x: x not in result, alphabet)))
            else:
                for t_char in target_chars:
                    if char == t_char:
                        result.append(t_char)
                        target_chars.remove(t_char)
                        break
                else:
                    result.append(char)
        result += list(target_chars)
        return ''.join(result)

