import heapq

def solve():
    import sys
    input = sys.stdin.readline

    T = int(input())
    for _ in range(T):
        N, Q = map(int, input().split())
        values = list(map(int, input().split()))
        adj = [[] for _ in range(N + 1)]
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if i != j:
                    cost = abs(values[i - 1] - values[j - 1]) + i + N - j
                    heapq.heappush(adj[i], (cost, j))

        res = []
        for _ in range(Q):
            x, y = map(int, input().split())
            heap = [(0, x, 1)]
            vis = set()
            while heap:
                cost, node, length = heapq.heappop(heap)
                if node == y:
                    res.append(f"{cost} {length}")
                    break
                if (node, length) in vis:
                    continue
                vis.add((node, length))
                for c, nei in adj[node]:
                    if nei not in vis:
                        heapq.heappush(heap, (cost + c, nei, length + 1))
        print('\n'.join(res))

