import math

def min_contributions(N, A, B, X, Y, Z, C):
    def needed(target):
        return math.ceil((target - A) / X)

    def can_reach(contributions):
        return A + sum(min(c, contributions) for c in C) >= target

    t = needed(Z)
    if B + Y * t >= Z:
        return "RIP"

    l, r = 0, t
    while l < r:
        m = (l + r) // 2
        if can_reach(m):
            r = m
        else:
            l = m + 1

    return l

