def find_triple_tree_decomposition(N, edges):
    if N % 3 != 1:
        return "NO"

    triples = []
    visited = [False] * (N + 1)
    stack = [(1, -1)]  # vertex, parent

    while stack:
        vertex, parent = stack.pop()
        if visited[vertex]:
            continue
        visited[vertex] = True

        neighbors = [n for n in range(2, N + 1) if (vertex, n) in edges or (n, vertex) in edges]
        if len(neighbors) == 3:
            a, b, c = neighbors
            triples.append(f"{vertex} {a} {b} {c}")
            stack.extend([(vertex, n) for n in (a, b, c)])
        elif len(neighbors) > 3:
            return "NO"

    if len(triples) != (N - 1) // 3:
        return "NO"

    return "YES\n" + "\n".join(triples)

