def ways_to_score(N, K):
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(K + 1):
        dp[1][i] = 1
    for i in range(2, N + 1):
        for j in range(1, min(i, K) + 1):
            dp[i][j] = (dp[i - 1][j - 1] + (j * dp[i - 1][j]) % MOD) % MOD
    return dp[N][K]

