def min_employees_informed(employees, friendships):
    def dfs(employee, visited):
        stack = [employee]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for friend in employees[current]:
                    if friend not in visited:
                        stack.append(friend)

    visited = set()
    for employee in range(len(employees)):
        if employee not in visited:
            dfs(employee, visited)
    return len(visited)

