def minimum_moves(books):
    n = len(books)
    position = {value: index for index, value in enumerate(books)}
    sorted_books = sorted(books)
    moves = 0
    for i in range(n):
        correct_value = sorted_books[i]
        if books[i] != correct_value:
            moves += 1
            new_index = position[correct_value]
            books[new_index], books[i] = books[i], books[new_index]
            position[books[new_index]], position[books[i]] = position[books[i]], position[books[new_index]]
    if moves == 0:
        moves += 1
    return moves

