def longest_subsequence(N, K, A, queries):
    max_length = 0
    current_length = 0
    ones = 0
    output = []

    for q in queries:
        if q == '!':
            current_length = 0
            ones = 0
            for i in range(N):
                if A[i] == 1:
                    ones += 1
                if i >= K:
                    if A[i - K] == 1:
                        ones -= 1
                if i + 1 <= N - K:
                    current_length = max(current_length, ones)
                else:
                    current_length = max(current_length, ones + sum(A[:i + 1 - K]))
                if i >= K - 1:
                    max_length = max(max_length, current_length)
            A = A[1:] + [A[0]]
        else:
            current_length = 0
            ones = 0
            for i in range(N):
                if A[i] == 1:
                    ones += 1
                if i >= K:
                    if A[i - K] == 1:
                        ones -= 1
                current_length = max(current_length, ones)
                if i >= K - 1:
                    max_length = max(max_length, current_length)
            output.append(max_length)

    return output

