def generate_balanced_parenthesis(n, k):
    if n % 2 == 1 or k % 2 == 1:
        return -1
    if k == n:
        return -1
    if k == 2:
        return '()'*n
    half = n // 2
    if half % (k-1) == 0:
        return '()'*half + '('*(half//(k-1))
    else:
        return -1

