def convert_to_decimal(number, base):
    number = number[::-1]
    decimal = 0
    for i, digit in enumerate(number):
        decimal += int(digit) * (base ** i)
    return decimal

def convert_to_base7(decimal, digits):
    result = ''
    while decimal > 0:
        result += str(decimal % 7)
        decimal //= 7
    return result.zfill(digits)

