def solve(N, M, board, Q, limits):
    # Create a prefix sum array for the board
    dp = [[0]*(M+1) for _ in range(N+1)]
    for i in range(1, N+1):
        for j in range(1, M+1):
            dp[i][j] = dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1] + (board[i-1][j-1] == '1')
    # Function to count mismatches in a sub-board
    def count_mismatches(x1, y1, x2, y2):
        return dp[x2][y2] - dp[x1][y2] - dp[x2][y1] + dp[x1][y1]
    # Function to check if a sub-board is valid
    def is_valid(x1, y1, x2, y2):
        mismatches = count_mismatches(x1, y1, x2, y2)
        return mismatches == 0 and (x2 - x1 + 1) == (y2 - y1 + 1)
    # Solve queries
    ans = []
    for limit in limits:
        max_side = 0
        for x1 in range(1, N+1):
            for y1 in range(1, M+1):
                for x2 in range(x1, N+1):
                    for y2 in range(y1, M+1):
                        if is_valid(x1, y1, x2, y2) and count_mismatches(x1, y1, x2, y2) <= limit:
                            max_side = max(max_side, min(x2 - x1 + 1, y2 - y1 + 1))
        ans.append(max_side)
    return ans

