def minimum_speeches(N, K, M, A):
    speeches = 0
    i = 0
    while i < N:
        if i + K <= N and sum(A[i:i+K]) < M:
            i += K
        else:
            j = i + 1
            while j < i + K and j <= N and A[j] == 0:
                j += 1
            if j > i + K:
                return -1
            A[i:j] = [A[i]*(M//A[i]) for _ in range(j - i)]
            speeches += 1
            i = j
    return speeches

