import math

def shortest_distance(path):
    x, y = 0, 0
    for direction in path:
        if direction == 'R':
            x += 1
        elif direction == 'L':
            x -= 1
        elif direction.isdigit():
            y += int(direction)
    direction = math.atan2(y, x) * 180 / math.pi
    if direction < 0:
        direction += 360
    if direction < 45 or direction >= 315:
        print(f"{math.hypot(x, y):.1f}N")
    elif direction < 135:
        print(f"{math.hypot(x, y):.1f}E")
    elif direction < 225:
        print(f"{math.hypot(x, y):.1f}S")
    else:
        print(f"{math.hypot(x, y):.1f}W")

