def rocket_stability(poly):
    n = len(poly) - 1
    rows = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        rows[0][i] = poly[i] if i % 2 == 0 else 0

    for i in range(1, n + 1):
        rows[i][0] = rows[i - 1][0] * (i + 1) - rows[i - 2][0] * (i + 1 - 1)

        for j in range(1, i + 1):
            if j % 2 == 1:
                rows[i][j] = rows[i - 1][j - 1] * (i + 1) - rows[i - 2][j] * (i + 1 - 1)
            else:
                rows[i][j] = 0

        if all(x == 0 for x in rows[i][1:]):
            for j in range(1, i + 1):
                rows[i][j] = rows[i - 1][j] * (n + 4 - i - 2 * j)

    for i in range(1, n + 1):
        if rows[i][0] == 0 and any(x != 0 for x in rows[i][1:]):
            return 0

    return 1 if all(rows[i][0] * rows[i + 1][0] >= 0 for i in range(n)) else 0

