    factors = [1]
    i = 2
    while i * i <= n:
        if n % i == 0:
            if i == m or m % i == 0:
                factors[-1] *= 2
            else:
                factors.append(i)
            n //= i
        else:
            i += 1
    if n > 1:
        if n == m or m % n == 0:
            factors[-1] *= 2
        else:
            factors.append(n)

    dp = [1] * (len(factors) + 1)
    for i in range(1, len(factors) + 1):
        dp[i] = pow(2, factors[i - 1] - 1, mod) * dp[i - 1] % mod

    res = dp[-1]
    if len(factors) > 1:
        res *= pow(2, len(factors) - 1, mod)
        res %= mod

    return len(factors), res

