def max_subarray(arr):
    max_sum = current_sum = arr[0]
    start = end = max_start = 0
    temp_start = 0

    for i in range(1, len(arr)):
        if arr[i] >= 0:
            current_sum += arr[i]
        else:
            current_sum = 0
            temp_start = i

        if current_sum > max_sum or (current_sum == max_sum and i - temp_start > end - start):
            max_sum = current_sum
            start = temp_start
            end = i
        elif current_sum == max_sum and i - temp_start == end - start and start > max_start:
            max_start = start

    return arr[start:end+1]

