        if arr[i] > peak:
            peak = arr[i]
        elif arr[i] < peak:
            return False
    return True

t = int(input())
for _ in range(t):
    n = int(input())
    arr = list(map(int, input().split()))
    print('Yes' if can_sharpen(arr) else 'No')
